namespace DshRemote.App.Services;

/// <summary>Small embedded images used by the demo client (image display/send regression).</summary>
internal static class DemoImages
{
    public const string Violet = "";

    public const string Mint = "";

    public static byte[] Decode(string base64) => Convert.FromBase64String(base64);

    public static byte[] VioletBytes() => Decode(Violet);

    public static byte[] MintBytes() => Decode(Mint);
}